var t=[{title:`Signalen om te verzamelen`,text:`Vergelijk de sets en herhalingen die je kreeg met wat je afrondde. Kijk naar gewicht, RPE van de training, spierpijn, gemiste trainingen en eventuele nieuwe beperkingen, want elk toont een ander deel van het beeld. Eén hoge RPE of één gemiste training bewijst niet dat het schema niet bij je past.`},{title:`Wanneer trainingen te makkelijk voelen`,text:`Haal je het doel steeds met stabiele techniek en lage inspanning, overweeg dan een paar herhalingen, een beetje gewicht of iets meer volume toe te voegen. Verander één variabele en kijk hoe je reageert voordat je iets anders toevoegt.`},{title:`Wanneer trainingen te zwaar voelen`,text:`Herhaaldelijk doelen missen, vorm die afbrokkelt of vermoeidheid die niet weggaat kunnen redenen zijn om het gewicht of volume te verlagen, een makkelijkere oefening te kiezen of meer herstel te nemen. Een nieuw pijnlijk gebied vraagt om een nieuwe blik op je beperkingen en mogelijk professioneel advies. Probeer het niet zelf vast te stellen.`},{title:`Voorbeeld`,text:`Je doet twee weken goblet squats met 3 × 10 op ongeveer RPE 5 met goede controle. De volgende keer kun je een iets zwaardere dumbbell kiezen en terugvallen op acht herhalingen. Blijft dezelfde beweging pijn doen, maak hem dan niet zomaar zwaarder.`},{title:`TrainUp gebruiken`,text:`Je schema verandert pas als je het opnieuw maakt, en nooit op basis van minder dan 3 trainingen. Bij recente pijn volgt geen verhoging. Waren 2 van je laatste 3 trainingen zeer zwaar (RPE 9 of hoger) of voor minder dan 60% afgerond, dan wordt het volgende schema lichter. Waren je laatste 4 licht (RPE 5 of lager) en volledig, dan wordt het een stap zwaarder, steeds één stap tegelijk. Pijnregels gaan voor prestaties, afgeronde trainingen worden nooit gewijzigd en je kiest zelf het gewicht.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Praktische richtlijnen van het ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};